package app.polka.nativeapp

import android.content.Context
import android.graphics.*
import android.os.*
import android.view.*
import android.widget.*
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import org.json.*
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.*
import java.io.File
import java.util.concurrent.TimeUnit

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[35],qualifiers="w360dp-h780dp-xxhdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class ShelfReorderTests {
 private lateinit var controller:org.robolectric.android.controller.ActivityController<MainActivity>
 private lateinit var a:MainActivity
 private fun drain(){repeat(8){Thread.sleep(40);Shadows.shadowOf(Looper.getMainLooper()).idleFor(80,TimeUnit.MILLISECONDS)}}
 @Before fun open(){org.robolectric.shadows.ShadowChoreographer.setFrameDelay(java.time.Duration.ofMillis(16));org.robolectric.shadows.ShadowChoreographer.setPaused(true);val c=ApplicationProvider.getApplicationContext<Context>();c.deleteDatabase("polka.sqlite");val db=Room.databaseBuilder(c,LibraryDb::class.java,"polka.sqlite").allowMainThreadQueries().build();val lib=Library(db);lib.initialize();lib.savePrefs(lib.prefs().put("motion","reduced").put("shelves",JSONArray(listOf("Проза","Другое"))));repeat(40){i->lib.save(JSONObject().put("id","book-$i").put("title",listOf("Смотритель маяка","Тихий берег","По ту сторону ночи","Дом у моря")[i%4]).put("authors",JSONArray().put("Полка")).put("pos",i).put("noFile",true).put("shelf",if(i%2==0)"Проза" else "Другое"))};lib.updateMarker();db.close();controller=Robolectric.buildActivity(MainActivity::class.java).setup();a=controller.get();drain();layout()}
 @After fun close(){controller.pause().stop().destroy();org.robolectric.shadows.ShadowChoreographer.setPaused(false)}
 private fun descendants(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{descendants(v.getChildAt(it))}else emptyList()
 private fun grid()=descendants(a.root).filterIsInstance<VirtualGrid>().single()
 private fun layout(w:Int=360,h:Int=780){val wm=View.MeasureSpec.makeMeasureSpec(a.d(w),View.MeasureSpec.EXACTLY);val hm=View.MeasureSpec.makeMeasureSpec(a.d(h),View.MeasureSpec.EXACTLY);a.root.measure(wm,hm);a.root.layout(0,0,a.d(w),a.d(h));Shadows.shadowOf(Looper.getMainLooper()).idle();a.root.measure(wm,hm);a.root.layout(0,0,a.d(w),a.d(h))}
 private fun advance(ms:Long){repeat(((ms+15)/16).toInt()){Shadows.shadowOf(Looper.getMainLooper()).idleFor(16,TimeUnit.MILLISECONDS)}}
 private fun screenshot(name:String){val b=Bitmap.createBitmap(a.root.width,a.root.height,Bitmap.Config.ARGB_8888);a.root.draw(Canvas(b));val dir=File(System.getProperty("qaOutputDir"),"edge-0.6.5").apply{mkdirs()};File(dir,"$name.png").outputStream().use{b.compress(Bitmap.CompressFormat.PNG,100,it)};b.recycle()}
 private var downTime=0L
 private fun touch(action:Int,x:Float,y:Float){if(action==MotionEvent.ACTION_DOWN)downTime=SystemClock.uptimeMillis();val e=MotionEvent.obtain(downTime,SystemClock.uptimeMillis(),action,x,y,0);a.root.dispatchTouchEvent(e);e.recycle()}
 private fun point(g:VirtualGrid,i:Int):PointF{val at=IntArray(2);g.getLocationOnScreen(at);val r=g.slot(i);val root=IntArray(2);a.root.getLocationOnScreen(root);return PointF(at[0]-root[0]+r.exactCenterX(),at[1]-root[1]+r.top+r.width()*.6f)}
 private fun hold(g:VirtualGrid,i:Int):PointF{val p=point(g,i);touch(MotionEvent.ACTION_DOWN,p.x,p.y);Shadows.shadowOf(Looper.getMainLooper()).idleFor(370,TimeUnit.MILLISECONDS);assertTrue("long press lifts card",g.reorder!!.active);return p}
 private fun ids(g:VirtualGrid)=(0..3).map{g.viewAt(it)?.contentDescription?.toString()}
 @Test fun holdMovesImmediatelyAndPersistsWithoutRebuildingOrOpeningDetail(){val g=grid();val before=g.viewAt(0);val id=a.currentBooks()[0].str("id");hold(g,0);val end=point(g,1);touch(MotionEvent.ACTION_MOVE,end.x,end.y);assertSame(before,g.viewAt(1));assertTrue(g.reorder!!.active);assertNull(a.bookDetailSheet);screenshot("dragging");touch(MotionEvent.ACTION_UP,end.x,end.y);drain();layout();assertSame(g,grid());assertNull(a.shelfReorder);assertEquals(1f,before!!.alpha,0f);assertEquals(id,a.currentBooks()[1].str("id"));assertNull(a.bookDetailSheet);screenshot("dropped");var saved="";a.work({saved=a.library.allBooks().sortedBy{it.optInt("pos")}[1].str("id")});drain();assertEquals(id,saved)}
 @Test fun quickTapStillOpensBookAndEarlyScrollDoesNotLift(){val g=grid();val p=point(g,0);touch(MotionEvent.ACTION_DOWN,p.x,p.y);touch(MotionEvent.ACTION_MOVE,p.x,p.y-a.d(40));Shadows.shadowOf(Looper.getMainLooper()).idleFor(500,TimeUnit.MILLISECONDS);assertFalse(g.reorder!!.active);touch(MotionEvent.ACTION_CANCEL,p.x,p.y);layout();val q=point(g,0);touch(MotionEvent.ACTION_DOWN,q.x,q.y);touch(MotionEvent.ACTION_UP,q.x,q.y);Shadows.shadowOf(Looper.getMainLooper()).idleFor(32,TimeUnit.MILLISECONDS);assertNotNull("tap posts the normal click action",a.bookDetailSheet)}
 @Test fun cancelAndBackRestoreOriginalSlotsAndRemoveGhost(){val g=grid();val before=g.viewAt(0);val saved=a.currentBooks().map{it.str("id")};hold(g,0);val q=point(g,1);touch(MotionEvent.ACTION_MOVE,q.x,q.y);touch(MotionEvent.ACTION_CANCEL,q.x,q.y);assertSame(before,g.viewAt(0));assertEquals(saved,a.currentBooks().map{it.str("id")});assertNull(a.shelfReorder);assertEquals(1f,before!!.alpha,0f);hold(g,0);touch(MotionEvent.ACTION_MOVE,q.x,q.y);a.onBackPressed();assertNull(a.shelfReorder);assertSame(before,g.viewAt(0))}
 @Test fun autoscrollKeepsGhostAndVirtualizationBounded(){val g=grid();hold(g,0);val scroller=descendants(a.root).filterIsInstance<ScrollView>().first();touch(MotionEvent.ACTION_MOVE,a.d(260).toFloat(),a.d(670).toFloat());Shadows.shadowOf(Looper.getMainLooper()).idleFor(16,TimeUnit.MILLISECONDS);advance(1800);assertTrue("scroll follows the held cover",scroller.scrollY>0);assertTrue(g.materializedCount<24);assertTrue(g.reorder!!.active);assertNotNull(g.pinned);assertTrue(g.pinned!!.isAttachedToWindow);screenshot("autoscroll");touch(MotionEvent.ACTION_CANCEL,a.d(260).toFloat(),a.d(670).toFloat());assertNull(a.shelfReorder)}
 @Test fun reorderedSubsetReusesGlobalSlotsAndNormalizesMissingPositions(){val db=Room.inMemoryDatabaseBuilder(a,LibraryDb::class.java).allowMainThreadQueries().build();try{val l=Library(db);l.savePrefs(JSONObject());repeat(6){i->l.save(JSONObject().put("id","$i").put("title","$i").put("pos",i).put("note","keep-$i"))};l.saveOrder(listOf("4","0","2"));val ordered=l.allBooks().sortedBy{it.optInt("pos")};assertEquals(listOf("4","1","0","3","2","5"),ordered.map{it.str("id")});assertTrue(ordered.all{it.str("note")=="keep-${it.str("id")}"});assertEquals("manual",l.prefs().str("sort"));val b=JSONObject(l.dao.book("3")!!.json).apply{remove("pos")};l.save(b);l.saveOrder(listOf("2","4","0"));assertEquals(6,l.allBooks().map{it.optInt("pos")}.distinct().size)}finally{db.close()}}
 @Test fun titleSortAlsoAllowsLongPressAndSwitchesToManual(){a.sort="title";a.prefs.put("sort","title");a.render(false,false);layout();val g=grid();val id=a.currentBooks()[0].str("id");hold(g,0);val q=point(g,1);touch(MotionEvent.ACTION_MOVE,q.x,q.y);touch(MotionEvent.ACTION_UP,q.x,q.y);drain();assertEquals("manual",a.sort);assertEquals(id,a.currentBooks()[1].str("id"))}
 @Test fun animatedNeighboursLandAndNoPingPongAtSameFingerPosition(){a.prefs.put("motion","normal");val g=grid();hold(g,0);val source=g.viewAt(0)!!;val neighbour=g.viewAt(1)!!;val q=point(g,1);touch(MotionEvent.ACTION_MOVE,q.x,q.y);assertSame(source,g.viewAt(1));assertTrue("FLIP starts at prior displayed location",kotlin.math.abs(neighbour.translationX)>1f);screenshot("motion-0");Shadows.shadowOf(Looper.getMainLooper()).idleFor(100,TimeUnit.MILLISECONDS);screenshot("motion-100");touch(MotionEvent.ACTION_MOVE,q.x,q.y);assertSame(source,g.viewAt(1));Shadows.shadowOf(Looper.getMainLooper()).idleFor(320,TimeUnit.MILLISECONDS);assertEquals(0f,neighbour.translationX,.5f);screenshot("motion-300");touch(MotionEvent.ACTION_UP,q.x,q.y);assertNotNull(a.shelfReorder);advance(400);assertNull(a.shelfReorder);assertEquals(1f,source.alpha,0f);assertNull(a.bookDetailSheet)}
 @Test fun backgroundCancelsUnfinishedReorderWithoutSaving(){val g=grid();val first=g.viewAt(0);val order=a.currentBooks().map{it.str("id")};hold(g,0);val q=point(g,1);touch(MotionEvent.ACTION_MOVE,q.x,q.y);controller.pause();assertNull(a.shelfReorder);assertSame(first,g.viewAt(0));assertEquals(order,a.currentBooks().map{it.str("id")});controller.resume()}
 private fun insets(landscape:Boolean=false,keyboard:Int=0):WindowInsets {val cut=DisplayCutout(Rect(if(landscape)a.d(34)else 0,if(landscape)0 else a.d(32),0,0),listOf(Rect(0,0,a.d(30),a.d(30))));return WindowInsets.Builder().setDisplayCutout(cut).setInsets(WindowInsets.Type.statusBars(),Insets.of(0,if(landscape)0 else a.d(24),0,0)).setInsets(WindowInsets.Type.navigationBars(),if(landscape)Insets.of(0,0,a.d(48),0)else Insets.of(0,0,0,a.d(24))).setInsets(WindowInsets.Type.mandatorySystemGestures(),Insets.of(0,0,0,a.d(28))).setInsets(WindowInsets.Type.ime(),Insets.of(0,0,0,a.d(keyboard))).build()}
 @Test fun wholeApplicationUsesCutoutGesturesKeyboardAndSideBars(){val i=insets();a.root.dispatchApplyWindowInsets(i);layout();assertEquals(a.d(32),a.appInsets.top);assertEquals(a.d(28),a.appInsets.bottom);assertEquals(0,a.root.paddingTop);assertEquals(0,a.root.paddingBottom);assertEquals(Color.TRANSPARENT,a.window.statusBarColor);assertEquals(Color.TRANSPARENT,a.window.navigationBarColor);screenshot("home-safe-dark");for(label in listOf("Полки","Цитаты","Для вас")){descendants(a.root).first{it.contentDescription==label}.performClick();drain();a.root.dispatchApplyWindowInsets(i);layout();assertEquals(a.d(32),a.appInsets.top);assertEquals(a.d(28),a.appInsets.bottom);screenshot("tab-$label")};a.showProfile(JSONObject().put("goal",10),7,false);a.root.dispatchApplyWindowInsets(i);layout();assertEquals(0,a.profileOverlay!!.top);assertEquals(a.root.height,a.profileOverlay!!.height);screenshot("profile-safe");a.root.dispatchApplyWindowInsets(insets(keyboard=280));layout();assertEquals(a.d(280),a.appInsets.bottom);a.root.dispatchApplyWindowInsets(insets(true));layout(780,360);assertEquals(a.d(34),a.appInsets.left);assertEquals(a.d(48),a.appInsets.right);screenshot("landscape-safe")}
 @Test fun sheetsReceiveOwnInsetsRatherThanAssumingActivityInsets(){val dialog=a.dialog().setTitle("Настройки полки").setTall(true).setView(a.edit("","Название")).setPositiveButton("Сохранить",null).show();val host=dialog.findViewById<ViewGroup>(android.R.id.content).getChildAt(0) as PolkaSheetFrame;host.dispatchApplyWindowInsets(insets(keyboard=280));assertEquals(0,host.paddingTop);assertEquals(0,host.paddingBottom);assertEquals(a.d(280),host.panel.paddingBottom);host.measure(View.MeasureSpec.makeMeasureSpec(a.d(360),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(a.d(732),View.MeasureSpec.EXACTLY));host.layout(0,0,a.d(360),a.d(732));val shot=Bitmap.createBitmap(host.width,host.height,Bitmap.Config.ARGB_8888);host.draw(Canvas(shot));val dir=File(System.getProperty("qaOutputDir"),"edge-0.6.5").apply{mkdirs()};File(dir,"sheet-keyboard-safe.png").outputStream().use{shot.compress(Bitmap.CompressFormat.PNG,100,it)};shot.recycle();host.dispatchApplyWindowInsets(insets(true));assertEquals(0,host.paddingLeft);assertEquals(0,host.paddingRight);assertEquals(a.d(34),host.panel.paddingLeft);assertEquals(a.d(48),host.panel.paddingRight);dialog.dismiss()}
 @Test fun lightHomeAndBookPanelStayInsideSystemZones(){a.prefs.put("ui","light");a.render(false,false);a.root.dispatchApplyWindowInsets(insets());layout();screenshot("home-safe-light");val g=grid();g.viewAt(0)!!.performClick();layout();a.root.viewTreeObserver.dispatchOnPreDraw();advance(600);a.root.dispatchApplyWindowInsets(insets());layout();val panel=a.bookDetailSheet!!.panelView;val r=Rect();panel.getGlobalVisibleRect(r);screenshot("book-panel-safe-light");assertTrue("panel top=${r.top}, root=${a.appInsets.top}",r.top>=a.d(32));assertTrue("panel bottom=${r.bottom}, root=${a.root.height}, pad=${a.appInsets.bottom}",r.bottom==a.root.height)}
 @Test fun scrimAndBookPanelFillFormerSystemBarGutters(){a.root.dispatchApplyWindowInsets(insets());layout();val g=grid();g.viewAt(0)!!.performClick();layout();a.root.viewTreeObserver.dispatchOnPreDraw();advance(600);a.root.dispatchApplyWindowInsets(insets());layout();val sheet=a.bookDetailSheet!!;assertEquals(0,sheet.top);assertEquals(a.root.height,sheet.height);val scrim=sheet.getChildAt(0);assertEquals(0,scrim.top);assertEquals(a.root.height,scrim.height);assertEquals(a.root.width,scrim.width);assertEquals(a.root.height,sheet.panelView.bottom);assertEquals(0,a.root.paddingBottom)
  val b=Bitmap.createBitmap(a.root.width,a.root.height,Bitmap.Config.ARGB_8888);a.root.draw(Canvas(b));assertNotEquals("status area must be dimmed, not a solid root-colour frame",a.bg,b.getPixel(a.d(180),a.d(4)));assertNotEquals("sheet surface must continue below gesture handle",a.bg,b.getPixel(a.d(180),a.root.height-a.d(2)));b.recycle();screenshot("modal-full-bleed-dark")}
 @Test fun scrolledBooksReachBehindTransparentStatusBar(){a.root.dispatchApplyWindowInsets(insets());layout();val scroll=descendants(a.root).filterIsInstance<ScrollView>().first();val g=grid();val loc=IntArray(2);g.getLocationOnScreen(loc);scroll.scrollTo(0,loc[1]-a.d(4));g.sync();layout();assertEquals(0,scroll.top);assertEquals(a.root.height,scroll.height);assertEquals(0,a.root.paddingTop);val b=Bitmap.createBitmap(a.root.width,a.root.height,Bitmap.Config.ARGB_8888);a.root.draw(Canvas(b));assertNotEquals("no opaque status-bar gutter over scrolled book covers",a.bg,b.getPixel(a.d(70),a.d(12)));b.recycle();screenshot("books-under-status-bar")}
 @Test @Config(sdk=[28]) fun legacyLightSystemBarsKeepReadableIcons(){ReaderWindow.configure(a.window,false,Color.WHITE);assertTrue(a.window.decorView.systemUiVisibility and View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR!=0);assertTrue(a.window.decorView.systemUiVisibility and View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR!=0);ReaderWindow.configure(a.window,false,Color.BLACK);assertEquals(0,a.window.decorView.systemUiVisibility and View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR)}
 @Test @Config(sdk=[28]) fun legacyBarsAndCutoutAreCombined(){val bars=Rect(0,a.d(24),0,a.d(48));val cut=DisplayCutout(Rect(a.d(30),a.d(32),0,0),listOf(Rect(0,0,a.d(30),a.d(32))));val ctor=WindowInsets::class.java.getConstructor(Rect::class.java,Rect::class.java,Rect::class.java,Boolean::class.javaPrimitiveType,Boolean::class.javaPrimitiveType,DisplayCutout::class.java);val native=ctor.newInstance(bars,Rect(),bars,false,false,cut);a.root.dispatchApplyWindowInsets(native);assertEquals(a.d(30),a.appInsets.left);assertEquals(a.d(32),a.appInsets.top);assertEquals(a.d(48),a.appInsets.bottom)}
}
